begin
  for r in
    select * from (values
      ('pack4-apple-polishing-cloth', 'easy', 'technology', 'How much does Apple charge for its official Polishing Cloth?', 'A small cleaning cloth for screens, sold by Apple since October 2021.', '/items/polishing-cloth.svg', 'Illustration of a soft gray cleaning cloth with a price tag', 19.00, 'Apple''s U.S. retail price', '2021-10-19', 'Apple''s Polishing Cloth costs $19. When it launched in 2021 it sold out for weeks, despite being a piece of cloth.', 'Apple Reveals Its Own Polishing Cloth For $19', 'SlashGear', 'https://www.slashgear.com/apple-reveals-its-own-polishing-cloth-for-19-19695824', 'Apple''s Polishing Cloth sells for a hefty price of $19.', 'Confirm on apple.com before verifying.'),
      ('pack4-supreme-brick', 'easy', 'luxury-goods', 'How much did the streetwear brand Supreme charge for a plain red clay brick with its logo on it?', 'The brick from Supreme''s Fall/Winter 2016 collection, at its original store price (not resale).', '/items/clay-brick.svg', 'Illustration of a red clay brick with a white label', 30.00, 'Original retail price', '2016-10-01', 'Supreme sold its logo brick for $30 in 2016. It sold out instantly and resold online for up to $1,000.', 'People Are Actually Paying $1,000 For This Brick On eBay', 'The Comeback', 'https://amp.thecomeback.com/general/people-are-actually-paying-1000-for-this-brick-on-ebay.html', 'which went at retail for $30.', ''),
      ('pack4-pet-rock', 'easy', 'everyday-products', 'How much did an original Pet Rock cost in 1975?', 'The 1970s fad: an ordinary stone sold in a cardboard box with breathing holes and a care manual.', '/items/pet-rock.svg', 'Illustration of a smiling gray rock sitting in a cardboard box with straw', 3.95, 'Original 1975 retail price', '1975-12-01', 'The Pet Rock retailed for $3.95 in 1975. The rocks cost less than a penny each, and creator Gary Dahl sold more than a million.', 'Hard Sell: A History of the Pet Rock', 'Mental Floss', 'https://www.mentalfloss.com/article/595180/pet-rock-history', 'could be purchased in bulk for less than a penny, retailed for $3.95', ''),
      ('pack4-disney-world-1971', 'easy', 'entertainment', 'How much was admission to Walt Disney World when it opened in 1971?', 'General admission to the Magic Kingdom in October 1971 (rides were paid for separately with ticket books).', '/items/park-ticket.svg', 'Illustration of a vintage admission ticket printed with 1971', 3.50, 'General admission price at opening, 1971', '1971-10-01', 'Walt Disney World opened on October 1, 1971, with admission of $3.50. Today a one-day ticket costs well over $100.', 'Here''s what a Disney World ticket cost when it opened in 1971', 'FOX 35 Orlando', 'https://www.fox35orlando.com/news/heres-what-a-disney-world-ticket-cost-when-it-opened-in-1971', 'admission to Disney World cost just $3.50 back in the day', ''),
      ('pack4-game-boy-1989', 'easy', 'technology', 'How much did the original Nintendo Game Boy cost when it came out in the U.S. in 1989?', 'The original gray handheld at its U.S. launch price.', '/items/handheld-classic.svg', 'Illustration of a retro handheld game device with a small screen and buttons', 89.99, 'U.S. launch price, 1989', '1989-07-31', 'The Game Boy launched in North America in 1989 for $89.99, bundled with Tetris. Nintendo sold more than 118 million Game Boys and Game Boy Colors.', 'Game Boy', 'Giant Bomb', 'https://giantbomb.com/wiki/Platforms/Game_Boy', 'Launch price: $89.99', 'Secondary source; the U.S. price is widely reported as $89.99 (sometimes $89.95).'),
      ('pack4-balenciaga-trash-pouch', 'medium', 'luxury-goods', 'How much was Balenciaga''s ''Trash Pouch'', a leather bag designed to look like a garbage bag?', 'The large black calfskin Trash Pouch, at its 2022 store price.', '/items/trash-pouch.svg', 'Illustration of a shiny black bag shaped like a tied garbage bag', 1790.00, 'Retail price', '2022-08-12', 'Balenciaga sold its garbage-bag-shaped Trash Pouch for $1,790 in 2022. A box of real trash bags costs about $9.', 'Balenciaga Is Selling a $1,790 Trash Bag', 'Apartment Therapy', 'https://www.apartmenttherapy.com/balenciaga-trash-bag-37118268', 'the price tag is expectedly not cheap: $1,790.', ''),
      ('pack4-virgin-mary-grilled-cheese', 'medium', 'entertainment', 'How much did a 10-year-old grilled cheese sandwich that seemed to show the Virgin Mary sell for on eBay?', 'The half-eaten sandwich a Florida woman kept for a decade, bought by an online casino in November 2004.', '/items/grilled-cheese.svg', 'Illustration of a grilled cheese sandwich on a plate', 28000.00, 'Final eBay sale price', '2004-11-22', 'The online casino GoldenPalace.com won the eBay auction for $28,000 in November 2004, then took the sandwich on tour.', '''Virgin Mary grilled cheese'' sells for $28,000', 'NBC News', 'https://www.nbcnews.com/id/wbna6511148', 'the item sold for $28,000 on eBay', ''),
      ('pack4-sealed-original-iphone', 'medium', 'technology', 'How much did a still-sealed, never-opened original 2007 iPhone sell for at auction?', 'A factory-sealed first-generation 4GB iPhone, sold by LCG Auctions in July 2023. It cost $499 new.', '/items/sealed-phone-box.svg', 'Illustration of a white phone box still wrapped in plastic', 190372.80, 'Final auction price', '2023-07-16', 'LCG Auctions sold the sealed 4GB original iPhone for $190,372.80 in July 2023, the 4GB model being rare because it was discontinued quickly.', 'Original 2007 4GB iPhone sells for $190,000 at auction, setting new record', 'iMore', 'https://www.imore.com/iphone/original-2007-4gb-iphone-sells-for-dollar190000-at-auction-setting-new-record', 'a 4GB iPhone from 2007, which sold for a total of $190,372.80.', ''),
      ('pack4-sealed-super-mario-64', 'medium', 'entertainment', 'How much did an unopened copy of the video game Super Mario 64 sell for at auction?', 'A factory-sealed, top-graded 1996 copy, sold by Heritage Auctions in July 2021.', '/items/sealed-game.svg', 'Illustration of a sealed video game box in a clear grading case', 1560000.00, 'Final auction price', '2021-07-11', 'Heritage Auctions sold a sealed Super Mario 64 for $1.56 million in July 2021, the first video game to sell for over $1 million.', 'Unopened ''Super Mario 64'' Game From 1996 Sells for $1.56M', 'NBC DFW (Associated Press)', 'https://www.nbcdfw.com/news/national-international/unopened-super-mario-64-game-from-1996-sells-for-1-56m/2678178/', 'An unopened copy of Nintendo''s "Super Mario 64" has sold at auction for $1.56 million.', ''),
      ('pack4-apollo-11-moon-bag', 'medium', 'science-and-infrastructure', 'How much did a cloth bag Neil Armstrong used to collect moon dust sell for at auction?', 'The Apollo 11 lunar sample bag, which still held traces of moon dust, sold by Sotheby''s on July 20, 2017.', '/items/moon-bag.svg', 'Illustration of a small white cloth bag with the moon behind it', 1812500.00, 'Final auction price including buyer''s premium', '2017-07-20', 'Sotheby''s sold the bag for $1,812,500 on July 20, 2017, the 48th anniversary of the moon landing. It had once been sold by mistake at a government auction for $995.', 'Apollo 11 Moon Rock Bag Sells for $1.8M at Sotheby''s Space Auction', 'Space.com', 'https://www.space.com/37571-apollo-11-moon-rock-bag-sold-auction.html', 'The $1.8 million includes Sotheby''s buyer''s premium.', ''),
      ('pack4-duct-taped-banana', 'hard', 'luxury-goods', 'How much did an artwork made of a banana duct-taped to a wall sell for at Sotheby''s?', 'Maurizio Cattelan''s ''Comedian'', sold in New York in November 2024. The buyer gets a certificate and instructions; the banana is replaced when it rots.', '/items/banana-auction.svg', 'Illustration of a banana on a pedestal next to an auction gavel', 6200000.00, 'Final auction price including fees', '2024-11-20', 'Sotheby''s sold ''Comedian'' for $6.2 million in November 2024. The buyer, crypto entrepreneur Justin Sun, then ate the banana.', 'That Viral Banana Duct-Taped to a Wall? It Just Sold for $6.2 Million', 'Smithsonian Magazine', 'https://www.smithsonianmag.com/smart-news/that-viral-banana-duct-taped-to-a-wall-it-just-sold-for-6-2-million-180985523/', 'Maurizio Cattelan''s viral duct-taped banana has sold for a total of $6.2 million.', ''),
      ('pack4-british-guiana-stamp', 'hard', 'luxury-goods', 'How much did the world''s rarest postage stamp, the British Guiana 1c Magenta, sell for in 2021?', 'A tiny one-cent stamp from 1856, sold by Sotheby''s in New York in June 2021, price including premium.', '/items/rare-stamp.svg', 'Illustration of an old magenta stamp with a sailing ship in a display frame', 8307000.00, 'Final auction price including buyer''s premium', '2021-06-08', 'Sotheby''s sold the British Guiana 1c Magenta for $8,307,000 on June 8, 2021. It is the only one known to exist.', 'British Guiana 1c magenta', 'Wikipedia', 'https://en.wikipedia.org/wiki/British_Guiana_1c_magenta', 'The stamp was put up for auction again at Sotheby''s in New York on 8 June 2021, where it sold for $8,307,000.', 'Consider adding a news source (e.g. Smithsonian or AP) when verifying.'),
      ('pack4-1933-double-eagle', 'hard', 'luxury-goods', 'How much did a single 1933 ''Double Eagle'' $20 gold coin sell for at auction?', 'The only 1933 Double Eagle that is legal to own, sold by Sotheby''s on June 8, 2021.', '/items/gold-coin.svg', 'Illustration of a gold coin with an eagle and the year 1933', 18900000.00, 'Final auction price', '2021-06-08', 'Sotheby''s sold the 1933 Double Eagle for $18.9 million in June 2021, the most ever paid for a coin. Almost all of them were melted down by the government in the 1930s.', '1933 Double Eagle Sells for $18.9 Million, Setting World Record for Most Valuable Coin', 'Smithsonian Magazine', 'https://www.smithsonianmag.com/smart-news/1933-double-eagle-sells-189-million-sets-world-record-most-valuable-coin-180977965/', 'becoming the world''s most valuable coin by selling for a whopping $18.9 million.', ''),
      ('pack4-voice-com-domain', 'hard', 'technology', 'How much did a company pay for the website address voice.com?', 'Just the domain name, bought by the blockchain company Block.one in 2019.', '/items/domain-name.svg', 'Illustration of a web browser address bar ending in .com with a SOLD badge', 30000000.00, 'Reported purchase price', '2019-07-24', 'Block.one paid $30 million for voice.com in 2019, one of the highest prices ever publicly reported for a domain name.', 'Voice.com sold for USD 30 million', 'SIDN', 'https://www.sidn.nl/en/news-and-blogs/voice-com-sold-for-usd-30-million', 'Last month, blockchain provider Block.one paid 30 million US dollars for the domain name voice.com.', ''),
      ('pack4-warhol-marilyn', 'hard', 'luxury-goods', 'How much did Andy Warhol''s ''Shot Sage Blue Marilyn'' portrait of Marilyn Monroe sell for at auction?', 'Christie''s New York, May 2022, final price including fees.', '/items/pop-art-auction.svg', 'Illustration of a colorful four-panel pop art painting in a gold frame with an auction gavel', 195000000.00, 'Final auction price including fees', '2022-05-09', 'Christie''s sold Warhol''s ''Shot Sage Blue Marilyn'' for $195 million with fees in May 2022, the most ever paid at auction for a work by an American artist.', 'Warhol portrait of Marilyn Monroe fetches record-setting $195 million at auction', 'NBC News', 'https://www.nbcnews.com/news/us-news/warhol-portrait-marilyn-monroe-fetches-record-setting-195-million-auct-rcna28053', 'Added fees gave it a final price of $195 million.', '')
    ) as t(slug, difficulty, cat, prompt, context, image, image_alt, amount, definition, ref_date, explanation,
           src_title, src_publisher, src_url, src_excerpt, src_notes)
  loop
    insert into public.questions (slug, prompt, context, difficulty, category_id, image_url, image_alt, image_credit, status, is_sample)
    values (r.slug, r.prompt, r.context, r.difficulty, (select id from public.categories where slug = r.cat),
            r.image, r.image_alt, 'Illustration: Pricele', 'draft', false)
    on conflict (slug) do nothing
    returning id into v_qid;

    if v_qid is not null then
      v_added := v_added + 1;
      insert into public.question_answers (question_id, answer_amount, answer_definition, reference_date, explanation)
      values (v_qid, r.amount, r.definition, r.ref_date::date, r.explanation);
      insert into public.question_sources (question_id, title, publisher, source_url, supporting_excerpt, verification_notes)
      values (v_qid, r.src_title, r.src_publisher, r.src_url, r.src_excerpt,
              concat_ws(' ', 'Researched 2026-10-18; re-check before verifying.', nullif(r.src_notes, '')));
    end if;
  end loop;
  raise notice 'Question pack pack-04: % new draft questions added', v_added;
